const rtdal005137Source0003 = `with_process_cleanup <- function(expr) {
  id <- ps_mark_tree()
  stat <- NULL
  do <- function() {
    on.exit(stat <<- ps_kill_tree(id), add = TRUE)
    withVisible(expr)
  }

  res <- do()

  ret <- list(
    result = res$value,
    visible = res$visible,
    process_cleanup = stat
  )
  class(ret) <- "with_process_cleanup"
  ret
}`

const rtdal005137Source0004 = `print.with_process_cleanup <- function(x, ...) {
  if (x$visible) {
    print(x$result)
  }
  if (length(x$process_cleanup)) {
    cat("!! Cleaned up the following processes:\n")
    print(x$process_cleanup)
  } else {
    cat("-- No leftover processes to clean up.\n")
  }
  invisible(x)
}`

