const rtdal005141Source0001 = `memoize <- function(fun) {
  fun
  cache <- NULL
  if (length(formals(fun)) > 0) {
    stop("Only memoizing functions without arguments")
  }
  dec <- function() {
    if (is.null(cache)) {
      cache <<- fun()
    }
    cache
  }
  attr(dec, "clear") <- function() cache <<- TRUE
  class(dec) <- c("memoize", class(dec))
  dec
}`

