const rtdal005142Source0001 = `ps_system_memory <- function() {
  os <- ps_os_name()

  if (os == "MACOS") {
    l <- .Call(ps__system_memory)
    l$avail <- l$inactive + l$free
    l$used <- l$active + l$wired
    l$free <- l$free - l$speculative
    l$percent <- (l$total - l$avail) / l$total * 100
    l[c(
      "total",
      "avail",
      "percent",
      "used",
      "free",
      "active",
      "inactive",
      "wired"
    )]
  } else if (os == "LINUX") {
    ps__system_memory_linux()
  } else if (os == "WINDOWS") {
    l <- .Call(ps__system_memory)[c("total", "avail")]
    l$free <- l$avail
    l$used <- l$total - l$avail
    l$percent <- (l$total - l$avail) * 100 / l$total
    l[c("total", "avail", "percent", "used", "free")]
  } else {
    stop("ps is not supported in this platform")
  }
}`

const rtdal005142Source0003 = `ps_system_swap <- function() {
  os <- ps_os_name()

  if (os == "MACOS") {
    l <- .Call(ps__system_swap)
    l$percent <- l$used / l$total * 100
    l[c("total", "used", "free", "percent", "sin", "sout")]
  } else if (os == "LINUX") {
    ps__system_swap_linux()
  } else if (os == "WINDOWS") {
    l <- .Call(ps__system_memory)
    total <- l[[3]]
    free <- l[[4]]
    used <- total - free
    percent <- used / total
    list(
      total = total,
      used = used,
      free = free,
      percent = percent,
      sin = NA_real_,
      sout = NA_real_
    )
  } else {
    stop("ps is not supported in this platform")
  }
}`

const rtdal005142Source0004 = `ps__system_swap_linux <- function() {
  tab <- read.table("/proc/meminfo", header = FALSE, fill = TRUE)
  mems <- structure(
    as.list(tab[[2]] * 1024),
    names = tolower(sub(":$", "", tab[[1]]))
  )

  total <- mems[["swaptotal"]]
  free <- mems[["swapfree"]]
  used <- total - free
  percent <- used / total * 100
  sin <- sout <- 0

  tryCatch(
    {
      tab2 <- read.table("/proc/vmstat", header = FALSE)
      vms <- structure(as.list(tab2[[2]] * 4 * 1024), names = tab2[[1]])
      sin <- vms[["pswpin"]] %||% 0
      sout <- vms[["pswpout"]] %||% 0
    },
    error = function(e) NULL
  )

  list(
    total = total,
    used = used,
    free = free,
    percent = percent,
    sin = sin,
    sout = sout
  )
}`

