const rtdal005143Source0003 = `ps_is_supported <- function() {
  os <- ps_os_type()
  if (os[["LINUX"]]) {
    # On Linux we need to check if /proc is readable
    supported <- FALSE
    tryCatch(
      {
        readLines("/proc/stat", warn = FALSE, n = 1)
        supported <- TRUE
      },
      error = function(e) e
    )
    supported
  } else {
    os <- os[setdiff(names(os), c("BSD", "POSIX"))]
    any(os)
  }
}`

