const rtdal005150Source0001 = `ps_pids <- function() {
  os <- ps_os_type()
  pp <- if (os[["MACOS"]]) {
    ps_pids_macos()
  } else if (os[["LINUX"]]) {
    ps_pids_linux()
  } else if (os[["WINDOWS"]]) {
    ps_pids_windows()
  } else {
    stop("Not implemented for this platform")
  }

  sort(pp)
}`

const rtdal005150Source0010 = `ps_cpu_count_physical <- function() {
  if (ps_os_type()[["LINUX"]]) {
    ps_cpu_count_physical_linux()
  } else {
    .Call(ps__cpu_count_physical)
  }
}`

