const rtdal005187Source0001 = "array_branch <- function(array, margin = NULL) {\n  dims <- dim(array) %||% length(array)\n  margin <- margin %||% seq_along(dims)\n\n  if (length(margin) == 0) {\n    list(array)\n  } else if (is.null(dim(array))) {\n    if (!identical(as.integer(margin), 1L)) {\n      cli::cli_abort(\n        \"{.arg margin} must be `NULL` or `1` with 1D arrays, not {.str {margin}}.\",\n        arg = \"margin\"\n      )\n    }\n    as.list(array)\n  } else {\n    out <- apply(array, margin, list)\n    if (!is.null(dim(out))) {\n      dim(out) <- NULL\n    }\n    list_flatten(out)\n  }\n}"

const rtdal005187Source0002 = `array_tree <- function(array, margin = NULL) {
  dims <- dim(array) %||% length(array)
  margin <- margin %||% seq_along(dims)

  if (length(margin) > 1) {
    new_margin <- ifelse(margin[-1] > margin[[1]], margin[-1] - 1, margin[-1])
    apply(array, margin[[1]], array_tree, new_margin)
  } else {
    array_branch(array, margin)
  }
}`

