const rtdal005211Source0002 = "list_simplify_internal <- function(\n  x,\n  simplify = NA,\n  ptype = NULL,\n  error_arg = caller_arg(x),\n  error_call = caller_env()\n) {\n  check_bool(simplify, allow_na = TRUE, call = error_call)\n  if (!is.null(ptype) && isFALSE(simplify)) {\n    cli::cli_abort(\n      \"Can't specify {.arg ptype} when `simplify = FALSE`.\",\n      arg = \"ptype\",\n      call = error_call\n    )\n  }\n\n  if (isFALSE(simplify)) {\n    return(x)\n  }\n\n  simplify_impl(\n    x,\n    strict = !is.na(simplify),\n    ptype = ptype,\n    error_arg = error_arg,\n    error_call = error_call\n  )\n}"

const rtdal005211Source0003 = `simplify_impl <- function(
  x,
  strict = TRUE,
  ptype = NULL,
  error_arg = caller_arg(x),
  error_call = caller_env()
) {
  obj_check_list(x, arg = error_arg, call = error_call)

  # Handle the cases where we definitely can't simplify
  if (strict) {
    list_check_all_vectors(x, arg = error_arg, call = error_call)
    list_check_all_size(x, 1, arg = error_arg, call = error_call)
  } else {
    can_simplify <- list_all_vectors(x) && all(list_sizes(x) == 1L)

    if (!can_simplify) {
      return(x)
    }
  }

  names <- vec_names(x)
  x <- vec_set_names(x, NULL)

  out <- tryCatch(
    list_unchop(
      x,
      ptype = ptype,
      error_arg = error_arg,
      error_call = error_call
    ),
    vctrs_error_incompatible_type = function(err) {
      if (strict || !is.null(ptype)) {
        cnd_signal(err)
      } else {
        x
      }
    }
  )
  if (!is.null(out)) {
    out <- vec_set_names(out, names)
  }
  out
}`

