const rtdal005212Source0001 = `list_transpose <- function(
  x,
  ...,
  template = NULL,
  simplify = NA,
  ptype = NULL,
  default = NULL
) {
  obj_check_list(x)
  check_dots_empty()

  if (length(x) == 0) {
    template <- integer()
  } else if (is.null(template)) {
    indexes <- map(x, vec_index)
    call <- current_env()
    withCallingHandlers(
      template <- reduce(indexes, vec_set_union),
      vctrs_error_ptype2 = function(e) {
        cli::cli_abort(
          "Can't combine named and unnamed vectors.",
          arg = template,
          call = call
        )
      }
    )
  }

  if (!is.character(template) && !is.numeric(template)) {
    cli::cli_abort(
      "{.arg template} must be a character or numeric vector, not {.obj_type_friendly {template}}.",
      arg = template
    )
  }

  simplify <- match_template(simplify, template)
  default <- match_template(default, template)
  ptype <- match_template(ptype, template)

  out <- rep_along(template, list())
  if (is.character(template)) {
    names(out) <- template
  }

  for (i in seq_along(template)) {
    idx <- template[[i]]
    res <- map(x, idx, .default = default[[i]])
    res <- list_simplify_internal(
      res,
      simplify = simplify[[i]] %||% NA,
      ptype = ptype[[i]],
      error_arg = result_index(idx)
    )
    out[[i]] <- res
  }

  out
}`

const rtdal005212Source0002 = `result_index <- function(idx) {
  if (is.character(idx)) {
    paste0("result$", idx)
  } else {
    paste0("result[[", idx, "]]")
  }
}`

const rtdal005212Source0003 = "match_template <- function(\n  x,\n  template,\n  error_arg = caller_arg(x),\n  error_call = caller_env()\n) {\n  if (is.character(template)) {\n    if (is_bare_list(x) && is_named(x)) {\n      extra_names <- setdiff(names(x), template)\n      if (length(extra_names)) {\n        cli::cli_abort(\n          \"{.arg {error_arg}} contains unknown names: {.str {extra_names}}.\",\n          arg = error_arg,\n          call = error_call\n        )\n      }\n\n      out <- rep_named(template, list(NULL))\n      out[names(x)] <- x\n      out\n    } else {\n      rep_named(template, list(x))\n    }\n  } else if (is.numeric(template)) {\n    if (is_bare_list(x) && length(x) > 0) {\n      if (length(x) != length(template)) {\n        cli::cli_abort(\n          \"Length of {.arg {error_arg}} ({length(x)}) and {.arg template} ({length(template)}) must be the same when transposing by position.\",\n          arg = error_arg,\n          call = error_call\n        )\n      }\n      x\n    } else {\n      rep_along(template, list(x))\n    }\n  } else {\n    cli::cli_abort(\"Invalid `template`\", .internal = TRUE)\n  }\n}"

