const rtdal005246Source0001 = `test_that("dots are correctly placed in the signature", {
  out <- partialised_body(partial(runif, n = rpois(1, 5)))
  exp <- expr(runif(n = rpois(1, 5), ...))
  expect_identical(out, exp)
})`

const rtdal005246Source0002 = `test_that("no lazy evaluation means arguments aren't repeatedly evaluated", {
  counter <- env(n = 0)
  lazy <- partial(list, n = {
    counter$n <- counter$n + 1
    NULL
  })
  walk(1:10, ~ lazy())
  expect_identical(counter$n, 10)

  counter <- env(n = 0)
  qq <- partial(
    list,
    n = !!{
      counter$n <- counter$n + 1
      NULL
    }
  )
  walk(1:10, ~ qq())
  expect_identical(counter$n, 1)
})`

const rtdal005246Source0003 = "test_that(\"partial() still works with functions using `missing()`\", {\n  fn <- function(x) missing(x)\n  expect_false(partial(fn, x = 3)())\n\n  fn <- function(x, y) missing(y)\n  expect_true(partial(fn)())\n  expect_true(partial(fn, x = 1)())\n  expect_false(partial(fn, x = 1, y = 2)())\n})"

const rtdal005246Source0004 = `test_that("partialised arguments are evaluated in their environments", {
  n <- 0

  partialised <- local({
    n <- 10
    partial(list, n = n)
  })

  expect_identical(partialised(), list(n = 10))
})`

const rtdal005246Source0005 = `test_that("partialised function is evaluated in its environment", {
  fn <- function(...) stop("tilt")

  partialised <- local({
    fn <- function(x) x
    partial(fn, x = "foo")
  })

  expect_identical(partialised(), "foo")
})`

const rtdal005246Source0006 = "test_that(\"partial() matches argument with primitives\", {\n  minus <- partial(`-`, .y = 5)\n  expect_identical(minus(1), -4)\n\n  minus <- partial(`-`, e2 = 5)\n  expect_identical(minus(1), -4)\n})"

const rtdal005246Source0007 = `test_that("partial() squashes quosures before printing", {
  foo <- function(x, y) y
  foo <- partial(foo, y = 3)

  # Reproducible environment tag
  environment(foo) <- global_env()

  expect_snapshot(foo)
})`

