const rtdal005262Source0001 = `test_that("when is deprecated", {
  expect_snapshot({
    . <- when(1:5 < 3 ~ 1, ~0)
  })
})`

const rtdal005262Source0002 = `test_that("when chooses the correct action", {
  local_options(lifecycle_verbosity = "quiet")

  x <-
    1:5 |>
    when(
      sum(.) <= 50 ~ sum(.),
      sum(.) <= 100 ~ sum(.) / 2,
      ~0
    )

  expect_equal(x, 15)

  y <-
    1:10 |>
    when(
      sum(.) <= 50 ~ sum(.),
      sum(.) <= 100 ~ sum(.) / 2,
      ~0
    )

  expect_equal(y, sum(1:10) / 2)

  z <-
    1:100 |>
    when(
      sum(.) <= 50 ~ sum(.),
      sum(.) <= 100 ~ sum(.) / 2,
      ~0
    )

  expect_equal(z, 0)
})`

const rtdal005262Source0003 = `test_that("named arguments work with when", {
  local_options(lifecycle_verbosity = "quiet")

  x <-
    1:10 |>
    when(
      sum(.) <= x ~ sum(.) * x,
      sum(.) <= 2 * x ~ sum(.) * x / 2,
      ~0,
      x = 60
    )

  expect_equal(x, sum(1:10) * 60)
})`

const rtdal005262Source0004 = `test_that("default values work without a formula", {
  local_options(lifecycle_verbosity = "quiet")

  x <- iris |>
    subset(Sepal.Length > 10) |>
    when(
      nrow(.) > 0 ~ .,
      head(iris, 10)
    )

  expect_equal(x, head(iris, 10))
})`

