const rtdal005268Source0001 = `test_that("list_c() concatenates vctrs of compatible types", {
  expect_identical(list_c(list(1L, 2:3)), c(1L, 2L, 3L))
  expect_identical(list_c(list(1, 2:3)), c(1, 2, 3))

  expect_snapshot(error = TRUE, list_c(list("a", 1)))
})`

const rtdal005268Source0002 = `test_that("list_c() can enforce ptype", {
  expect_snapshot(error = TRUE, list_c(list("a"), ptype = integer()))
})`

const rtdal005268Source0003 = `test_that("list_c() strips outer names and preserves inner names (#997)", {
  expect_equal(list_c(list(x = 1:2, y = 3:4)), 1:4)
  expect_equal(list_c(list(c(a = 1), c(b = 2))), c(a = 1, b = 2))
})`

const rtdal005268Source0004 = `test_that("list_cbind() column-binds compatible data frames", {
  df1 <- data.frame(x = 1:2)
  df2 <- data.frame(y = 1:2)
  df3 <- data.frame(z = 1:3)

  expect_equal(list_cbind(list(df1, df2)), data.frame(x = 1:2, y = 1:2))
  expect_snapshot(error = TRUE, {
    list_cbind(list(df1, df3))
  })
})`

const rtdal005268Source0005 = `test_that("list_cbind() can enforce size", {
  df1 <- data.frame(x = 1:2)
  expect_snapshot(error = TRUE, {
    list_cbind(list(df1), size = 3)
  })
})`

const rtdal005268Source0006 = "test_that(\"list_rbind() row-binds compatible data.frames\", {\n  df1 <- data.frame(x = 1)\n  df2 <- data.frame(x = 2, y = 1)\n  df3 <- data.frame(x = \"a\", stringsAsFactors = FALSE)\n\n  expect_equal(list_rbind(list(df1, df2)), data.frame(x = 1:2, y = c(NA, 1)))\n\n  # and names don't make a difference unless `names_to` is set\n  out <- list_rbind(list(a = df1, b = df2))\n  expect_equal(out, data.frame(x = c(1, 2), y = c(NA, 1)))\n\n  expect_snapshot(error = TRUE, {\n    list_rbind(list(df1, df3))\n  })\n})"

