const rtdal005282Source0002 = `test_that("All parallel map variants fall back to sequential with no daemons set", {
  expect_identical(
    map(list(x = 1, y = 2), in_parallel(\(x) list(x))),
    map(list(x = 1, y = 2), \(x) list(x))
  )
  expect_equal(map2(1, 2, in_parallel(\(x, y) x)), list(1))
  expect_identical(pmap(list(), in_parallel(~ 1)), list())
})`

const rtdal005282Source0003 = `mirai::daemons(1, dispatcher = FALSE)`

const rtdal005282Source0004 = `on.exit(mirai::daemons(0), add = TRUE)`

const rtdal005282Source0005 = "test_that(\"Can't use `...` in a parallel map\", {\n  expect_snapshot(error = TRUE, {\n    map(list(x = 1, y = 2), in_parallel(\\(x) list(x)), a = \"wrong\")\n  })\n})"

const rtdal005282Source0006 = "test_that(\"Crated function environment is attached to search path\", {\n  # Use of `median()` without the `stats::` namespace\n  expect_equal(map_dbl(1:2, in_parallel(\\(x) median(c(1, 1, x)))), c(1, 1))\n})"

const rtdal005282Source0007 = `test_that("preserves names", {
  out <- map(list(x = 1, y = 2), in_parallel(\(x) identity(x)))
  expect_equal(names(out), c("x", "y"))
})`

const rtdal005282Source0008 = `test_that("works with matrices/arrays (#970)", {
  expect_identical(
    map_int(matrix(1:4, nrow = 2), in_parallel(\(x) identity(x))),
    1:4
  )
})`

const rtdal005282Source0009 = `test_that("all inform about location of problem", {
  skip_if_not_installed("carrier")

  expect_snapshot(error = TRUE, {
    map_int(1:3, in_parallel(\(x, bad = 2:1) if (x == 3) bad else x))
    map_int(1:3, in_parallel(\(x, bad = "x") if (x == 3) bad else x))
    map(
      1:3,
      in_parallel(\(x, bad = stop("Doesn't work")) if (x == 3) bad else x)
    )
  })

  cnd <- catch_cnd(map(
    1:3,
    in_parallel(\(x, bad = stop("Doesn't work")) if (x == 3) bad else x)
  ))
  expect_s3_class(cnd, "purrr_error_indexed")
  expect_equal(cnd$location, 3)
  expect_equal(cnd$name, NULL)
})`

const rtdal005282Source0010 = `test_that("error location uses name if present", {
  skip_if_not_installed("carrier")

  expect_snapshot(error = TRUE, {
    map_int(
      c(a = 1, b = 2, c = 3),
      in_parallel(\(x, bad = stop("Doesn't work")) if (x == 3) bad else x)
    )
    map_int(
      c(a = 1, b = 2, 3),
      in_parallel(\(x, bad = stop("Doesn't work")) if (x == 3) bad else x)
    )
  })

  cnd <- catch_cnd(map(
    c(1, 2, c = 3),
    in_parallel(\(x, bad = stop("Doesn't work")) if (x == 3) bad else x)
  ))
  expect_s3_class(cnd, "purrr_error_indexed")
  expect_equal(cnd$location, 3)
  expect_equal(cnd$name, "c")
})`

const rtdal005282Source0011 = `test_that("0 length input gives 0 length output", {
  expect_equal(map(list(), in_parallel(\(x) identity(x))), list())
  expect_equal(map(NULL, in_parallel(\(x) identity(x))), list())

  expect_equal(map_lgl(NULL, in_parallel(\(x) identity(x))), logical())
})`

const rtdal005282Source0012 = `test_that("map() always returns a list", {
  expect_bare(map(mtcars, in_parallel(\(x) mean(x))), "list")
})`

const rtdal005282Source0013 = `test_that("types automatically coerced correctly", {
  expect_identical(
    map_lgl(c(NA, 0, 1), in_parallel(\(x) identity(x))),
    c(NA, FALSE, TRUE)
  )

  expect_identical(
    map_int(c(NA, FALSE, TRUE), in_parallel(\(x) identity(x))),
    c(NA, 0L, 1L)
  )
  expect_identical(
    map_int(c(NA, 1, 2), in_parallel(\(x) identity(x))),
    c(NA, 1L, 2L)
  )

  expect_identical(
    map_dbl(c(NA, FALSE, TRUE), in_parallel(\(x) identity(x))),
    c(NA, 0, 1)
  )
  expect_identical(
    map_dbl(c(NA, 1L, 2L), in_parallel(\(x) identity(x))),
    c(NA, 1, 2)
  )

  expect_identical(map_chr(NA, in_parallel(\(x) identity(x))), NA_character_)
})`

const rtdal005282Source0014 = `test_that("logical and integer NA become correct double NA", {
  expect_identical(
    map_dbl(list(NA, NA_integer_), in_parallel(\(x) identity(x))),
    c(NA_real_, NA_real_)
  )
})`

const rtdal005282Source0015 = `test_that("map forces arguments in same way as base R", {
  f_map <- map(1:2, in_parallel(\(i) \(x) x + i))
  f_base <- lapply(1:2, \(i) \(x) x + i)

  expect_equal(f_map[[1]](0), f_base[[1]](0))
  expect_equal(f_map[[2]](0), f_base[[2]](0))
})`

const rtdal005282Source0016 = `test_that("primitive dispatch correctly", {
  skip_if_not_installed("carrier")

  method <- \(x) "dispatched!"
  x <- structure(list(), class = "test_class")
  expect_identical(
    map(
      list(x, x),
      in_parallel(\(x) as.character(x), as.character.test_class = method)
    ),
    list("dispatched!", "dispatched!")
  )
})`

const rtdal005282Source0017 = `test_that("map() with empty input copies names", {
  named_list <- named(list())
  expect_identical(
    map(named_list, in_parallel(\(x) identity(x))),
    named(list())
  )
  expect_identical(
    map_lgl(named_list, in_parallel(\(x) identity(x))),
    named(lgl())
  )
  expect_identical(
    map_int(named_list, in_parallel(\(x) identity(x))),
    named(int())
  )
  expect_identical(
    map_dbl(named_list, in_parallel(\(x) identity(x))),
    named(dbl())
  )
  expect_identical(
    map_chr(named_list, in_parallel(\(x) identity(x))),
    named(chr())
  )
})`

