const rtdal005285Source0001 = `test_that("can pluck/chuck from NULL", {
  expect_equal(pluck(NULL, 1), NULL)
  expect_snapshot(chuck(NULL, 1), error = TRUE)
})`

const rtdal005285Source0002 = `test_that("can pluck vector types ", {
  x <- list(
    lgl = c(TRUE, FALSE),
    int = 1:2,
    dbl = c(1, 2.5),
    chr = c("a", "b"),
    cpx = c(1 + 1i, 2 + 2i),
    raw = charToRaw("ab"),
    lst = list(1, 2)
  )

  expect_equal(pluck(x, "lgl", 2), FALSE)
  expect_identical(pluck(x, "int", 2), 2L)
  expect_equal(pluck(x, "dbl", 2), 2.5)
  expect_equal(pluck(x, "chr", 2), "b")
  expect_equal(pluck(x, "cpx", 2), 2 + 2i)
  expect_equal(pluck(x, "raw", 2), charToRaw("b"))
  expect_equal(pluck(x, "lst", 2), 2)
})`

const rtdal005285Source0003 = `test_that("unsupported types have useful error", {
  expect_snapshot(error = TRUE, {
    pluck(quote(x), 1)
    pluck(quote(f(x, 1)), 1)
    pluck(expression(1), 1)
  })
})`

const rtdal005285Source0004 = `test_that("dots must be unnamed", {
  expect_snapshot(pluck(1, a = 1), error = TRUE)
  expect_snapshot(chuck(1, a = 1), error = TRUE)
})`

const rtdal005285Source0005 = `test_that("can pluck by position (positive and negative)", {
  x <- list("a", "b", "c")

  expect_equal(pluck(x, 1), "a")
  expect_equal(pluck(x, -1), "c")

  expect_equal(pluck(x, 0), NULL)
  expect_equal(pluck(x, 4), NULL)
  expect_equal(pluck(x, -4), NULL)
  expect_equal(pluck(x, -5), NULL)

  expect_snapshot(chuck(x, 0), error = TRUE)
  expect_snapshot(chuck(x, 4), error = TRUE)
  expect_snapshot(chuck(x, -4), error = TRUE)
  expect_snapshot(chuck(x, -5), error = TRUE)
})`

const rtdal005285Source0006 = `test_that("special numbers don't match", {
  x <- list()

  expect_equal(pluck(x, NA_integer_), NULL)
  expect_equal(pluck(x, NA_real_), NULL)
  expect_equal(pluck(x, NaN), NULL)
  expect_equal(pluck(x, Inf), NULL)
  expect_equal(pluck(x, -Inf), NULL)

  expect_snapshot(chuck(x, NA_integer_), error = TRUE)
  expect_snapshot(chuck(x, NA_real_), error = TRUE)
  expect_snapshot(chuck(x, NaN), error = TRUE)
  expect_snapshot(chuck(x, Inf), error = TRUE)
  expect_snapshot(chuck(x, -Inf), error = TRUE)
})`

const rtdal005285Source0007 = `test_that("can pluck by name", {
  x <- list(a = "a")

  expect_equal(pluck(x, "a"), "a")

  expect_equal(pluck(x, "b"), NULL)
  expect_equal(pluck(x, NA_character_), NULL)
  expect_equal(pluck(x, ""), NULL)

  expect_snapshot(chuck(x, "b"), error = TRUE)
  expect_snapshot(chuck(x, NA_character_), error = TRUE)
  expect_snapshot(chuck(x, ""), error = TRUE)
})`

const rtdal005285Source0008 = `test_that("even if names don't exist", {
  x <- list("a")

  expect_equal(pluck(x, "a"), NULL)
  expect_snapshot(chuck(x, "a"), error = TRUE)
})`

const rtdal005285Source0009 = `test_that("matches first name if duplicated", {
  x <- list(1, 2, 3, 4, 5)
  names(x) <- c("a", "a", NA, "", "b")

  expect_equal(pluck(x, "a"), 1)
})`

const rtdal005285Source0010 = `test_that("empty and NA names never match", {
  x <- list(1, 2, 3)
  names(x) <- c("", NA, "x")

  expect_equal(pluck(x, "x"), 3)

  expect_equal(pluck(x, ""), NULL)
  expect_equal(pluck(x, NA_character_), NULL)

  expect_snapshot(chuck(x, ""), error = TRUE)
  expect_snapshot(chuck(x, NA_character_), error = TRUE)
})`

const rtdal005285Source0011 = `test_that("require length 1 character/double vectors", {
  expect_snapshot(error = TRUE, {
    pluck(1, 1:2)
    pluck(1, integer())
    pluck(1, NULL)
    pluck(1, TRUE)
  })
})`

const rtdal005285Source0012 = `test_that("validate index even when indexing NULL", {
  expect_snapshot(error = TRUE, {
    pluck(NULL, 1:2)
    pluck(NULL, TRUE)
  })
})`

const rtdal005285Source0013 = `test_that("can pluck 0-length object", {
  expect_equal(pluck(list(integer()), 1), integer())
})`

const rtdal005285Source0014 = `test_that("supports splicing", {
  x <- list(list(bar = 1, foo = 2))
  idx <- list(1, "foo")
  expect_identical(pluck(x, !!!idx), 2)
})`

const rtdal005285Source0015 = `test_that("can pluck attributes", {
  x <- structure(
    list(
      structure(
        list(),
        x = 1
      )
    ),
    y = 2
  )

  expect_equal(pluck(x, attr_getter("y")), 2)
  expect_equal(pluck(x, 1, attr_getter("x")), 1)
})`

const rtdal005285Source0016 = `test_that("attr_getter() uses exact (non-partial) matching", {
  x <- 1
  attr(x, "labels") <- "foo"

  expect_identical(attr_getter("labels")(x), "foo")
  expect_identical(attr_getter("label")(x), NULL)
})`

const rtdal005285Source0017 = `test_that("attr_getter() evaluates eagerly", {
  getters <- new_list(2)
  attrs <- c("foo", "bar")
  for (i in seq_along(attrs)) {
    getters[[i]] <- attr_getter(attrs[[i]])
  }

  x <- structure(list(), foo = "foo", bar = "bar")
  expect_identical(getters[[1]](x), "foo")
})`

const rtdal005285Source0018 = `test_that("accessors throw correct errors", {
  expect_snapshot(error = TRUE, {
    pluck(1:3, function() NULL)
    pluck(1:3, function(x, y) y)
  })
})`

const rtdal005285Source0019 = `test_that("pluck() functions dispatch on base getters", {
  expect_identical(pluck(iris, "Species", levels), levels(iris$Species))
})`

const rtdal005285Source0020 = `test_that("pluck() supports primitive and built-in functions (#404)", {
  x <- list(1:2)
  expect_equal(pluck(x, 1, as.character), c("1", "2"))
  expect_equal(pluck(x, 1, sum), 3)
})`

const rtdal005285Source0021 = `test_that("can pluck/chuck environment by name", {
  x <- new_environment(list(x = 10))

  expect_equal(pluck(x, "x"), 10)
  expect_equal(pluck(x, "y"), NULL)
  expect_equal(pluck(x, NA_character_), NULL)

  expect_snapshot(chuck(x, "y"), error = TRUE)
  expect_snapshot(chuck(x, NA_character_), error = TRUE)
})`

const rtdal005285Source0022 = `test_that("environments error with invalid indices", {
  expect_snapshot(pluck(environment(), 1), error = TRUE)
  expect_snapshot(pluck(environment(), letters), error = TRUE)
})`

const rtdal005285Source0023 = `test_that("plucking promise from an environment evaluates it", {
  x <- new_environment()
  delayedAssign("q", { 1 }, assign.env = x)
  expect_equal(pluck(x, "q"), 1)
})`

const rtdal005285Source0024 = `newA <- methods::setClass("A", list(a = "numeric"))`

const rtdal005285Source0025 = `test_that("can pluck/chuck from S4 objects", {
  A <- newA(a = 1)
  expect_equal(pluck(A, "a"), 1)
  expect_equal(pluck(A, "b"), NULL)
  expect_equal(pluck(A, NA_character_), NULL)

  expect_snapshot(chuck(A, "b"), error = TRUE)
  expect_snapshot(chuck(A, NA_character_), error = TRUE)
})`

const rtdal005285Source0026 = `test_that("S4 objects error with invalid indices", {
  A <- newA(a = 1)
  expect_snapshot(pluck(A, 1), error = TRUE)
  expect_snapshot(pluck(A, letters), error = TRUE)
})`

const rtdal005285Source0027 = "test_that(\"pluck() dispatches on vector methods\", {\n  new_test_pluck <- function(x) {\n    structure(list(x), class = \"test_pluck\")\n  }\n\n  inner <- list(a = \"foo\", b = list(\"bar\"))\n  x <- list(new_test_pluck(inner))\n\n  with_bindings(\n    .env = global_env(),\n    `[[.test_pluck` = function(x, i) .subset2(x, 1)[[i]],\n    names.test_pluck = function(x) names(.subset2(x, 1)),\n    length.test_pluck = function(x) length(.subset2(x, 1)),\n    {\n      expect_identical(pluck(x, 1, 1), \"foo\")\n      expect_identical(pluck(x, 1, \"b\", 1), \"bar\")\n      expect_identical(chuck(x, 1, 1), \"foo\")\n      expect_identical(chuck(x, 1, \"b\", 1), \"bar\")\n    }\n  )\n\n  # With faulty length() method\n  with_bindings(\n    .env = global_env(),\n    `[[.test_pluck` = function(x, i) .subset2(x, 1)[[i]],\n    length.test_pluck = function(x) NA,\n    {\n      expect_null(pluck(x, 1, 1))\n      expect_snapshot(chuck(x, 1, 1), error = TRUE)\n    }\n  )\n\n  # With faulty names() method\n  with_bindings(\n    .env = global_env(),\n    `[[.test_pluck` = function(x, i) .subset2(x, 1)[[i]],\n    names.test_pluck = function(x) NA,\n    length.test_pluck = function(x) length(.subset2(x, 1)),\n    {\n      expect_null(pluck(x, 1, \"b\", 1))\n      expect_snapshot(chuck(x, 1, \"b\", 1), error = TRUE)\n    }\n  )\n})"

const rtdal005285Source0028 = `test_that("pluck<- is an alias for assign_in()", {
  x <- list(list(bar = 1, foo = 2))
  pluck(x, 1, "foo") <- 30
  expect_identical(x, list(list(bar = 1, foo = 30)))
})`

