const rtdal005326Source0008 = `Hill <- function(formula, tau = 0.1, data = NULL, ...){
    y <- model.response(model.frame(formula, data))
    X <- model.matrix(formula, data)
    Hill.fit(X, y, tau)
}`

const rtdal005326Source0009 = `Hill.fit <- function(X, y, tau, ...){
    if(tau > 0.5){ # Right tail
	X <- -X 
	y <- -y 
	tau = 1-tau
    }
    F <- rq.fit(X, y, tau = tau, ...)
    yhat <- F$fitted.values
    z <- log(ifelse(y <= yhat, abs(y/yhat), 1))
    z <- z[is.finite(z)]
    z <- list(xi = sum(z)/(length(z)*tau), tau = tau, F = F)
    class(z) <- "Hill"
    z
}`

